statusFormula:
if(prop("Done"), "✅Done", 
  if(prop("Archives"), "🗃️ Archive ", 
    if(prop("Next "), "🔵 Next goal", 
      if(prop("Hold"), "▶️ Hold ", 
        if(today() > prop("Snooze Deadline"), " 🔴 Late Snooze " 
	+ formatDate(prop("Snooze Deadline"), "dddd"), 
          if(today() >= prop("Deadline Date") and today() <= prop("Snooze Deadline"), "⏰ In progress", 
            if(today() > prop("Deadline Date"), " 🔴 Late Deadline ".style("c","b","red","red_background") +
	 formatDate(prop("Deadline Date"),"dddd").style("c","b","red","red_background"), 
              if(today() >= prop(" Start  Date") and today() <= prop("Deadline Date"), "🟢 In progress" + 
	formatDate( prop(" Start  Date"), " dddd"), 
                if(empty(prop(" Start  Date")) and empty(prop("Deadline Date")), "▶ Not Started", 
                  if((formatDate(now(), "W") == formatDate(prop(" Start  Date"), "W")) and (prop(" Start  Date") > now()), "🔵 The Next Goal" + formatDate(prop(" Start  Date"), " dddd"), 
                    if((toNumber(formatDate(now(), "W")) + 1) == toNumber(formatDate(prop(" Start  Date"), "W")), "↗ The Next Goal " + 
	formatDate(prop(" Start  Date"), " dddd"), "↗ The future")
                  )
                )
              )
            )
          )
        )
      )
    )
  )
) + 
if(prop("Done") or prop("Archives") or (empty(prop(" Start  Date")) and empty(prop("Deadline Date"))), "", " ➜ " + 
  if(((prop("Completed") / prop("Goal")) >= 1), "100% Completed 💪".style("c","b","green","green_background"), 
    (substring(" ██████████", 0, floor((prop("Completed") / prop("Goal")) * 10)) + substring("░░░░░░░░░░", 0, ceil(10 - ((prop("Completed") / prop("Goal")) * 10)))) + " " + format(round((prop("Completed") / prop("Goal")) * 100)) + if(empty(prop("Completed")), "0%", "%")
  )
)

hijriMonthFormula:
lets(
  /* تاريخ بداية التقويم الهجري (16 يوليو 622 م) */
  startDate, parseDate("0622-07-16"),
  /* حساب الأيام بين تاريخ البداية والتاريخ المقدم */
  elapsedDays, dateBetween(prop(" Start  Date"), startDate, "days"),

  /* حساب السنة الهجرية */
  hijriYear, floor(elapsedDays / 354.367),
  /* حساب الدورة الثلاثينية */
  cycleYear, mod(hijriYear, 30) + 1,

  /* تحديد ما إذا كانت سنة كبيسة (355 يوم) */
  leapYears, [2, 5, 7, 10, 13, 16, 18, 21, 24, 26, 29],
  isLeapYear, leapYears.includes(cycleYear),

  /* حساب عدد الأيام المنقضية في السنوات السابقة مع مراعاة السنوات الكبيسة */
  daysBeforeYear, hijriYear * 354 + floor(hijriYear / 30) * 11,

  /* حساب يوم السنة الهجرية */
  dayOfYear, elapsedDays - daysBeforeYear,

  /* تحديد أطوال الشهور الهجرية (30 يوم للفردي، 29 يوم للزوجي) */
  monthLengths, [30, 29, 30, 29, 30, 29, 30, 29, 30, 29, 30, 29],

  /* إضافة يوم للشهر الأخير في السنوات الكبيسة */
  adjustedMonthLengths, if(isLeapYear,
    [30, 29, 30, 29, 30, 29, 30, 29, 30, 29, 30, 30],
    monthLengths
  ),

  /* حساب الشهر من يوم السنة */
  hijriMonth, ifs(
    dayOfYear < adjustedMonthLengths.at(0), 0,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1), 1,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2), 2,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3), 3,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4), 4,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4) + adjustedMonthLengths.at(5), 5,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4) + adjustedMonthLengths.at(5) + adjustedMonthLengths.at(6), 6,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4) + adjustedMonthLengths.at(5) + adjustedMonthLengths.at(6) + adjustedMonthLengths.at(7), 7,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4) + adjustedMonthLengths.at(5) + adjustedMonthLengths.at(6) + adjustedMonthLengths.at(7) + adjustedMonthLengths.at(8), 8,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4) + adjustedMonthLengths.at(5) + adjustedMonthLengths.at(6) + adjustedMonthLengths.at(7) + adjustedMonthLengths.at(8) + adjustedMonthLengths.at(9), 9,
    dayOfYear < adjustedMonthLengths.at(0) + adjustedMonthLengths.at(1) + adjustedMonthLengths.at(2) + adjustedMonthLengths.at(3) + adjustedMonthLengths.at(4) + adjustedMonthLengths.at(5) + adjustedMonthLengths.at(6) + adjustedMonthLengths.at(7) + adjustedMonthLengths.at(8) + adjustedMonthLengths.at(9) + adjustedMonthLengths.at(10), 10,
    11
  ),

  /* الحصول على اسم الشهر الهجري بالعربية */
  monthName, ifs(
    hijriMonth == 0, "📅 محرم",
    hijriMonth == 1, "📅 صفر",
    hijriMonth == 2, "📅 ربيع الأول",
    hijriMonth == 3, "📅 ربيع الثاني",
    hijriMonth == 4, "📅 جمادى الأولى",
    hijriMonth == 5, "📅 جمادى الآخرة",
    hijriMonth == 6, "📅 رجب",
    hijriMonth == 7, "📅 شعبان",
    hijriMonth == 8, "📅 رمضان",
    hijriMonth == 9, "📅 شوال",
    hijriMonth == 10, "📅 ذو القعدة",
    "📅 ذو الحجة"
  ),

  /* إرجاع النتيجة النهائية */
  if(empty(prop(" Start  Date")), "", monthName)
)
